display:flex;justify-content:space-between;gap:14px;padding:11px 15px;background:linear-gradient(90deg,#dbeafe,#ecfeff);color:#163b73;font-weight:900}.worked-body{padding:16px}.steps{display:grid;gap:9px;margin:12px 0}.step{position:relative;padding:12px 13px 12px 45px;border-radius:11px;background:#f8fafc;border:1px solid var(--line)}.step:before{content:attr(data-step);position:absolute;left:12px;top:11px;display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#dbeafe;color:#1d4ed8;font-size:12px;font-weight:950}.compare,.timeline{width:100%;border-collapse:collapse;margin:13px 0}.compare th,.compare td,.timeline th,.timeline td{padding:11px 12px;border:1px solid var(--line);vertical-align:top}.compare th,.timeline th{background:#eff6ff;color:#1e3a8a;text-align:left}.diagram{margin:15px 0;padding:18px;border-radius:14px;background:#f8fbff;border:1px solid var(--line);overflow:auto}.flow{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.flow-box{min-width:125px;padding:11px 13px;border-radius:11px;background:#fff;border:1px solid #bfdbfe;text-align:center;font-weight:850}.arrow{color:#2563eb;font-size:24px;font-weight:950}.code{margin:13px 0;padding:15px;border-radius:13px;background:#0f172a;color:#e2e8f0;font:15px/1.65 "SFMono-Regular",Consolas,monospace;white-space:pre-wrap;overflow:auto}.glossary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.glossary-item{padding:12px 13px;border-radius:11px;background:#f8fafc;border:1px solid var(--line)}.glossary-item strong{color:#1d4ed8}.checklist{display:grid;gap:9px}.check{padding:11px 12px;border-radius:11px;background:#f0fdf4;border:1px solid #bbf7d0}
.exercise-summary{margin-bottom:15px;padding:16px;border-radius:14px;background:linear-gradient(135deg,#f8fbff,#eff6ff);border:1px solid #bfdbfe}.exercise-stats{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.stat{padding:8px 12px;border-radius:10px;background:#fff;border:1px solid #dbeafe}.stat strong{color:#1d4ed8}.exercise-list{display:grid;gap:12px}.exercise{border:1px solid var(--line);border-radius:13px;background:#fff;overflow:hidden}.exercise>summary{position:relative;padding:13px 48px 13px 15px;list-style:none;background:#f8fafc;font-weight:850;cursor:pointer}.exercise>summary::-webkit-details-marker{display:none}.exercise>summary:after{content:"+";position:absolute;right:14px;top:9px;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#dbeafe;color:#1d4ed8;font-size:20px}.exercise[open]>summary:after{content:"−"}.exercise-body{padding:15px 17px 17px}.answer-zone{margin-top:12px;padding:13px;border-radius:11px;background:#f8fafc;border:1px solid var(--line)}.answer-zone label{display:block;margin-bottom:5px;font-size:13px;font-weight:850;color:#334155}.answer-zone input,.answer-zone select,.answer-zone textarea{width:100%;padding:9px 10px;border:1px solid #cbd5e1;border-radius:9px;background:#fff}.answer-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.feedback{min-height:25px;margin-top:8px;font-weight:800}.feedback.ok{color:#15803d}.feedback.bad{color:#b91c1c}.hint{display:none;margin-top:8px;padding:9px 10px;border-radius:9px;background:#fffbeb;border:1px solid #fde68a;color:#713f12}.solution{display:none;margin-top:10px;padding:13px;border-radius:11px;background:#f0fdf4;border:1px solid #bbf7d0}.exercise[data-view="solution"] .question-view{display:none}.exercise[data-view="solution"] .solution{display:block}.exercise[data-view="solution"]>summary{background:#f0fdf4}.progress-track{height:10px;border-radius:999px;background:#dbeafe;overflow:hidden;margin-top:11px}.progress-track span{display:block;height:100%;width:0;background:linear-gradient(90deg,#2563eb,#06b6d4);transition:width .25s ease}
.footer{margin-top:24px;padding:20px 24px;border-radius:16px;background:#102a56;color:#dbeafe}.footer a{color:#a5f3fc}.source-note{margin-top:8px;color:#cbd5e1;font-size:14px}
.library-hero{padding:48px 52px}.library-toolbar{display:flex;gap:12px;align-items:center;margin:22px 0;padding:14px;border:1px solid var(--line);border-radius:14px;background:#fff}.library-toolbar input{flex:1;padding:11px 13px;border:1px solid #cbd5e1;border-radius:10px}.filters{display:flex;gap:8px}.filter{border:1px solid #bfdbfe;background:#eff6ff;color:#1d4ed8;border-radius:999px;padding:8px 12px;font-weight:850;cursor:pointer}.filter.active{background:#2563eb;color:#fff}.library-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.lesson-card{display:flex;flex-direction:column;min-height:340px;padding:20px;border-radius:17px;background:#fff;border:1px solid var(--line);box-shadow:0 10px 25px rgba(31,55,89,.055)}.lesson-card.hidden{display:none}.lesson-card .card-top{display:flex;justify-content:space-between;gap:12px;align-items:start}.lesson-card h2{margin:10px 0 7px;font-size:22px;line-height:1.25}.lesson-card p{margin:0;color:var(--muted);font-size:15px}.category{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:12px;font-weight:900}.source-pages{font-size:12px;color:#64748b;font-weight:800}.topic-list{display:flex;flex-wrap:wrap;gap:6px;margin:13px 0}.topic{padding:4px 7px;border-radius:8px;background:#f1f5f9;color:#334155;font-size:12px;font-weight:750}.card-progress{margin-top:auto;padding-top:14px}.card-progress-row{display:flex;justify-content:space-between;font-size:13px;font-weight:800;color:#475569}.mini-track{height:7px;margin-top:6px;border-radius:999px;background:#e2e8f0;overflow:hidden}.mini-track span{display:block;height:100%;width:0;background:linear-gradient(90deg,#2563eb,#06b6d4)}.card-actions{display:flex;gap:8px;margin-top:14px}.card-actions a{flex:1;padding:9px 10px;border-radius:9px;text-align:center;text-decoration:none;font-weight:850}.open-link{background:#2563eb;color:#fff}.pdf-link{background:#e9f1fb;color:#173d77}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin:20px 0}.overview-card{padding:16px;border-radius:14px;background:#fff;border:1px solid var(--line);text-align:center}.overview-card strong{display:block;font-size:26px;color:#1d4ed8}.overview-card span{color:var(--muted);font-size:13px;font-weight:750}
